-- LOCAL PROPOSAL ONLY. Requires finance_history_v2; no live application or grants.
BEGIN;
CREATE TABLE finance_history_v2.correction_proposals(proposal_id uuid PRIMARY KEY,store_id uuid NOT NULL REFERENCES public.stores(id),request_key text NOT NULL,payload jsonb NOT NULL,proposal_hash text NOT NULL,proposed_by uuid NOT NULL REFERENCES auth.users(id),observed_at timestamptz NOT NULL,UNIQUE(store_id,request_key));
CREATE TABLE finance_history_v2.correction_reviews(proposal_id uuid PRIMARY KEY REFERENCES finance_history_v2.correction_proposals(proposal_id),proposal_hash text NOT NULL,decision text NOT NULL CHECK(decision IN('approve','reject')),note text NOT NULL,reviewed_by uuid NOT NULL REFERENCES auth.users(id),observed_at timestamptz NOT NULL);
CREATE TABLE finance_history_v2.correction_overlays(version_id uuid PRIMARY KEY,store_id uuid NOT NULL,source_id text NOT NULL,previous_hash text NOT NULL,body jsonb NOT NULL,row_hash text NOT NULL,proposal_id uuid NOT NULL UNIQUE REFERENCES finance_history_v2.correction_proposals(proposal_id),FOREIGN KEY(store_id,source_id) REFERENCES finance_history_v2.events(store_id,source_id));
CREATE TABLE finance_history_v2.correction_versions(version_id uuid PRIMARY KEY REFERENCES finance_history_v2.correction_overlays(version_id),store_id uuid NOT NULL REFERENCES public.stores(id),date_from date NOT NULL,date_to date NOT NULL,parent_version_id uuid NOT NULL,proposal_id uuid NOT NULL UNIQUE REFERENCES finance_history_v2.correction_proposals(proposal_id),sales_revision text NOT NULL,cost_revision text NOT NULL,source_manifest jsonb NOT NULL,manifest_hash text NOT NULL);
CREATE TABLE finance_history_v2.correction_selections(selection_id uuid PRIMARY KEY,store_id uuid NOT NULL REFERENCES public.stores(id),date_from date NOT NULL,date_to date NOT NULL,previous_version_id uuid NOT NULL UNIQUE,version_id uuid NOT NULL UNIQUE REFERENCES finance_history_v2.correction_versions(version_id),proposal_hash text NOT NULL,selected_by uuid NOT NULL REFERENCES auth.users(id),observed_at timestamptz NOT NULL);
CREATE TABLE finance_history_v2.version_heads(store_id uuid NOT NULL REFERENCES public.stores(id),date_from date NOT NULL,date_to date NOT NULL,version_id uuid NOT NULL REFERENCES finance_history_v2.correction_versions(version_id),selection_id uuid NOT NULL REFERENCES finance_history_v2.correction_selections(selection_id),PRIMARY KEY(store_id,date_from,date_to));
CREATE TABLE finance_history_v2.correction_receipts(store_id uuid NOT NULL REFERENCES public.stores(id),request_key text NOT NULL,proposal_hash text NOT NULL,version_id uuid NOT NULL REFERENCES finance_history_v2.correction_versions(version_id),selection_id uuid NOT NULL REFERENCES finance_history_v2.correction_selections(selection_id),receipt jsonb NOT NULL,PRIMARY KEY(store_id,request_key));
DO $protect_corrections$ DECLARE n text; BEGIN FOREACH n IN ARRAY ARRAY['correction_proposals','correction_reviews','correction_overlays','correction_versions','correction_selections','correction_receipts'] LOOP
 EXECUTE format('CREATE TRIGGER history_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON finance_history_v2.%I FOR EACH STATEMENT EXECUTE FUNCTION finance_history_v2.reject_change()',n);
END LOOP;
FOREACH n IN ARRAY ARRAY['correction_proposals','correction_reviews','correction_overlays','correction_versions','correction_selections','version_heads','correction_receipts'] LOOP EXECUTE format('ALTER TABLE finance_history_v2.%I ENABLE ROW LEVEL SECURITY',n);END LOOP;END $protect_corrections$;
REVOKE ALL ON finance_history_v2.correction_proposals,finance_history_v2.correction_reviews,finance_history_v2.correction_overlays,finance_history_v2.correction_versions,finance_history_v2.correction_selections,finance_history_v2.version_heads,finance_history_v2.correction_receipts FROM PUBLIC;
COMMIT;
